@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

/*
 * Gauge Dark: dense operations dashboard.
 * Deep indigo-charcoal ground, warm gauge-gold accent, and a NESTED depth
 * hierarchy: every surface level carries its own shadow recipe so panels
 * within panels read as physically stacked instruments.
 *
 * Surface ladder (dark -> light):
 *   well (recessed)  0.135  inputs, tracks, code wells
 *   background       0.158  page ground
 *   card             0.205  level-1 panel
 *   nested           0.235  level-2 panel inside a panel
 *   secondary        0.262  raised control surface
 */

:root {
  --background: oklch(0.158 0.012 285);
  --foreground: oklch(0.93 0.008 85);

  --card: oklch(0.205 0.014 283);
  --card-foreground: oklch(0.93 0.008 85);

  --popover: oklch(0.228 0.015 283);
  --popover-foreground: oklch(0.93 0.008 85);

  --primary: oklch(0.8 0.115 85);
  --primary-foreground: oklch(0.24 0.05 85);

  --secondary: oklch(0.262 0.016 283);
  --secondary-foreground: oklch(0.88 0.01 85);

  --muted: oklch(0.235 0.014 283);
  --muted-foreground: oklch(0.66 0.018 281);

  --accent: oklch(0.288 0.018 283);
  --accent-foreground: oklch(0.93 0.008 85);

  --destructive: oklch(0.55 0.19 25);
  --destructive-foreground: oklch(0.97 0.015 25);

  --border: oklch(0.31 0.018 285);
  --input: oklch(0.135 0.012 285);
  --ring: oklch(0.8 0.115 85);
  --radius: 0.5rem;

  /* ── Gauge namespace: the DS's own material tokens ─────────────────── */
  /* Level-2 panel fill (a panel sitting inside a card) */
  --gauge-nested: oklch(0.235 0.015 283);
  /* Recessed well border (slightly lighter than the well itself) */
  --gauge-well-border: oklch(0.268 0.016 285);
  /* Gold control material: rim + vertical gradient stops */
  --gauge-rim: oklch(0.6 0.1 78);
  --gauge-grad-top: oklch(0.845 0.108 88);
  --gauge-grad-bottom: oklch(0.755 0.118 80);
  /* Warm accent hairline (the gold "needle" lines on panels and tabs) */
  --gauge-line: oklch(0.8 0.115 85 / 0.6);
  --gauge-line-soft: oklch(0.8 0.115 85 / 0.25);
  /* Status hues for dense metric UI */
  --gauge-ok: oklch(0.74 0.12 152);
  --gauge-warn: oklch(0.76 0.14 70);

  /* ── Nested-depth shadow hierarchy (defining trait) ────────────────── */
  /* Level 1: page panel. Inset top highlight + contact + ambient. */
  --shadow-panel: inset 0 0.0625rem 0 oklch(1 0 0 / 0.05),
    0 0 0 0.0625rem oklch(0 0 0 / 0.25), 0 0.0625rem 0.125rem oklch(0 0 0 / 0.45),
    0 0.375rem 1.25rem -0.375rem oklch(0 0 0 / 0.5);
  /* Level 2: panel inside a panel. Same recipe, tighter throw. */
  --shadow-nested: inset 0 0.0625rem 0 oklch(1 0 0 / 0.04),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.4), 0 0.1875rem 0.5rem -0.125rem oklch(0 0 0 / 0.35);
  /* Recessed well: inputs, tracks, code surfaces. Pressed INTO the panel. */
  --shadow-well: inset 0 0.0625rem 0.125rem oklch(0 0 0 / 0.5),
    inset 0 0.125rem 0.375rem oklch(0 0 0 / 0.3), 0 0.0625rem 0 oklch(1 0 0 / 0.04);
  /* Raised neutral control: secondary buttons, toggles, thumbs. */
  --shadow-raised: inset 0 0.0625rem 0 oklch(1 0 0 / 0.09),
    0 0.0625rem 0.125rem oklch(0 0 0 / 0.45), 0 0.125rem 0.3125rem -0.0625rem oklch(0 0 0 / 0.35);
  /* Gold primary material: bright top bevel, dark base bevel, warm glow. */
  --shadow-primary: inset 0 0.0625rem 0 oklch(1 0 0 / 0.35),
    inset 0 -0.0625rem 0 oklch(0 0 0 / 0.18), 0 0.0625rem 0.125rem oklch(0 0 0 / 0.5),
    0 0.1875rem 0.625rem -0.125rem oklch(0.8 0.115 85 / 0.28);
  /* Floating layer: popovers, menus, dialogs. Deepest throw in the stack. */
  --shadow-pop: inset 0 0.0625rem 0 oklch(1 0 0 / 0.06),
    0 0 0 0.0625rem oklch(0 0 0 / 0.3), 0 0.5rem 1.5rem -0.25rem oklch(0 0 0 / 0.55),
    0 1.25rem 3rem -0.75rem oklch(0 0 0 / 0.5);
  /* Gold focus halo, appended after a surface's own shadow. */
  --shadow-focus: 0 0 0 0.1875rem oklch(0.8 0.115 85 / 0.25);

  /* Typography: dense data UI. Sans for chrome, mono for readings. */
  --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
    "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: ui-monospace, "SF Mono", SFMono-Regular, Menlo, Consolas,
    "Liberation Mono", monospace;

  /* ── Chart palette: warm instrument hues, gold-led ─────────────────── */
  --chart-1: oklch(0.8 0.115 85);
  --chart-2: oklch(0.74 0.12 100);
  --chart-3: oklch(0.7 0.07 60);
  --chart-4: oklch(0.64 0.13 30);
  --chart-5: oklch(0.68 0.15 45);

  /* --- Motion (crisp profile) ---
     Bare transition-* and ease-* classes read these; durations are
     duration-fast, duration-base and duration-slow once installed. */
  --transition-duration-fast: 120ms;
  --transition-duration-base: 160ms;
  --transition-duration-slow: 220ms;
  --ease-out: cubic-bezier(0.25, 0.46, 0.45, 0.94);
  --ease-in-out: cubic-bezier(0.455, 0.03, 0.515, 0.955);
  --ease-in: cubic-bezier(0.55, 0.085, 0.68, 0.53);
  --default-transition-duration: var(--transition-duration-fast);
  --default-transition-timing-function: var(--ease-out);

  /* AI parts: the label that marks what a model wrote. */
  --ai-label: var(--muted);
  --ai-label-foreground: var(--foreground);
}

/* Registers duration-fast, duration-base and duration-slow, which the
   components use. `reference` writes no variable that points at itself. */
@theme inline reference {
  --transition-duration-fast: var(--transition-duration-fast);
  --transition-duration-base: var(--transition-duration-base);
  --transition-duration-slow: var(--transition-duration-slow);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 0.25rem);
  --radius-md: calc(var(--radius) - 0.125rem);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 0.25rem);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family: var(--font-sans);
  }
  body {
    @apply bg-background text-foreground antialiased;
    font-feature-settings: "tnum" 1, "cv05" 1;
  }

  ::selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }
  /* stylelint-disable-next-line selector-no-vendor-prefix */
  ::-moz-selection {
    background-color: var(--primary);
    color: var(--primary-foreground);
  }

  /* Let textareas grow with their content instead of nested scrolling. */
  textarea {
    resize: vertical;
  }
  @supports (field-sizing: content) {
    textarea {
      field-sizing: content;
      max-height: 20lh;
      overflow-y: auto;
    }
  }

  /* Reserve the scrollbar gutter so the page keeps its width whenever the
     scrollbar comes and goes: content loading in, moving between a short
     and a tall page, or a scroll lock that just hides overflow. */
  html {
    scrollbar-gutter: stable;
  }
  @supports (scrollbar-gutter: stable) {
    html body[data-scroll-locked] {
      /* Radix's scroll lock re-adds the scrollbar width as body margin. The
         stable gutter already reserves it, so without this the two stack and
         opening a dialog shifts the page the other way. */
      margin-right: 0 !important;
    }
  }
}

@layer utilities {
  /* Show an invalid field on the field itself, not only in the message under
     it. Declared after Tailwind's utilities, so it wins over the field's own
     border and focus-ring classes. */
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
  [role="radiogroup"][aria-invalid="true"] [role="radio"] {
    border-color: var(--destructive);
  }
  [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]):focus-visible,
  [role="radiogroup"][aria-invalid="true"] [role="radio"]:focus-visible {
    border-color: var(--destructive);
    --tw-ring-color: color-mix(in oklch, var(--destructive) 35%, transparent);
  }

  /* Shake a field once when it turns invalid. */
  @keyframes deny-shake {
    25% { translate: -0.09375rem; }
    50% { translate: 0.109375rem; }
    75% { translate: -0.109375rem; }
  }
  @media (prefers-reduced-motion: no-preference) {
    [aria-invalid="true"]:is(input, textarea, select, [role="combobox"], [role="checkbox"], [role="radio"]),
    [role="radiogroup"][aria-invalid="true"] [role="radio"],
    [data-input-otp-container]:has([aria-invalid="true"]) {
      animation: deny-shake 250ms linear;
    }
  }
}

:root {
  --layout-density: compact;
  --layout-density-source: design-system;
  --layout-sidebar: calc(var(--spacing, 0.25rem) * 46);
  --layout-inset: calc(var(--spacing, 0.25rem) * 4);
  --layout-section-gap: calc(var(--spacing, 0.25rem) * 6);
  --layout-column-gap: calc(var(--spacing, 0.25rem) * 3);
  --layout-card-padding: calc(var(--spacing, 0.25rem) * 4);
}

